`,s.jsxs(e.p,{children:[s.jsx(e.strong,{children:"Gradient Boosting:"})," (1) robust defaults ",s.jsx(e.code,{children:"subsample=0.8, colsample_bytree=0.8, max_depth=4, learning_rate=0.1"}),"; (2) find M via early stopping (held-out 15–20%, up to M_max=1000); (3) test budget equivalence — ",s.jsx(e.code,{children:"learning_rate=0.05"})," with ~2×M*, often generalizes better; (4) grid ",s.jsx(e.code,{children:"max_depth"})," [2–6] (3–4 usual for tabular); (5) fine-tune ",s.jsx(e.code,{children:"min_child_weight"}),", ",s.jsx(e.code,{children:"subsample"}),", ",s.jsx(e.code,{children:"colsample_bytree"}),", ",s.jsx(e.code,{children:"reg_lambda"})," last."]}),`
